/**
 * Contrast rules and the colour resolver behind them, shared by the guard
 * (contrast.test.ts) and the gallery's theme studio. Pure: no fs, no DOM.
 *
 * A theme file becomes "scopes" (light, dark, each data-theme preset, each
 * data-accent preset on top of those, each with data-contrast="more"); a scope
 * is the flat list of custom properties the root element ends up with. var()
 * and color-mix(in oklab, …) are resolved, translucent colours are flattened
 * over the surface they sit on, and every rule is a WCAG ratio floor.
 */
import { converter, formatRgb, parse, wcagContrast, type Color } from "culori"

export type Decls = Record<string, string>
export type Block = { selector: string; decls: Decls; media?: string }
export type Rule = [fg: string, bgs: string[], min: number]
export type Check = { fg: string; bg: string; ratio: number; min: number; ok: boolean; detail: string }

/* ---------- parsing ---------- */

/** Rule blocks with custom properties, in source order. `media` is the enclosing @media prelude, if any. */
export function parseBlocks(css: string): Block[] {
  const clean = css.replace(/\/\*[\s\S]*?\*\//g, "")
  const out: Block[] = []
  const stack: string[] = []
  let buf = ""
  for (const ch of clean) {
    if (ch === "{") {
      stack.push(buf.split(";").pop()!.trim())
      buf = ""
    } else if (ch === "}") {
      const prelude = stack.pop() ?? ""
      const decls: Decls = {}
      for (const d of buf.matchAll(/(--[\w-]+)\s*:\s*([^;]+?)\s*(?:!important\s*)?(?:;|$)/g)) decls[d[1]] = d[2].trim()
      const media = stack.filter((p) => p.startsWith("@media")).join(" ") || undefined
      if (Object.keys(decls).length && !prelude.startsWith("@")) out.push({ selector: prelude, decls, media })
      buf = ""
    } else buf += ch
  }
  return out
}

/** `html[data-x]` and `:root[data-x]` mean the same element as `[data-x]`. */
const norm = (s: string) => s.trim().replace(/^(?:html|:root)(?=[.[:])/, "")

function pick(blocks: Block[], pred: (selector: string) => boolean): Decls {
  return blocks
    .filter((b) => !b.media && b.selector.split(",").some((s) => pred(norm(s))))
    .reduce<Decls>((acc, b) => ({ ...acc, ...b.decls }), {})
}

/** Values of `data-<attr>="…"` the blocks define (`theme` → neutral presets, `accent` → accent presets). */
export function presetNames(blocks: Block[], attr: "theme" | "accent"): string[] {
  return [...new Set(blocks.flatMap((b) => [...b.selector.matchAll(new RegExp(`data-${attr}="([\\w-]+)"`, "g"))].map((m) => m[1])))]
}

function layer(blocks: Block[], attr: string, v: string) {
  return {
    light: pick(blocks, (s) => s === `[data-${attr}="${v}"]`),
    dark: pick(blocks, (s) => s === `.dark[data-${attr}="${v}"]` || s === `[data-${attr}="${v}"].dark` || s === `[data-${attr}="${v}"] .dark`),
  }
}

/** What the root element ends up with for one combination of knobs. Later layers win, as in the cascade. */
export function composeScope(blocks: Block[], opts: { theme?: string; accent?: string; dark?: boolean; more?: boolean } = {}): Decls {
  const n = opts.theme ? layer(blocks, "theme", opts.theme) : { light: {}, dark: {} }
  const a = opts.accent ? layer(blocks, "accent", opts.accent) : { light: {}, dark: {} }
  const light = pick(blocks, (s) => s === ":root")
  const decls = opts.dark
    ? { ...light, ...pick(blocks, (s) => s === ".dark"), ...n.light, ...n.dark, ...a.light, ...a.dark }
    : { ...light, ...n.light, ...a.light }
  return opts.more ? { ...decls, ...moreLayer(blocks) } : decls
}

/** The data-contrast="more" declarations alone; they override whatever skin is underneath. */
export function moreLayer(blocks: Block[]): Decls {
  return pick(blocks, (s) => s === '[data-contrast="more"]')
}

export type Scope = { name: string; decls: Decls; more: boolean }

/**
 * Every combination a project can switch on: neutral preset (data-theme) × accent preset
 * (data-accent) × light / dark × data-contrast="more".
 */
export function themeScopes(blocks: Block[]): Scope[] {
  const hasMore = Object.keys(moreLayer(blocks)).length > 0
  const out: Scope[] = []
  for (const theme of ["", ...presetNames(blocks, "theme")]) {
    for (const accent of ["", ...presetNames(blocks, "accent")]) {
      const label = [theme, accent && `accent ${accent}`].filter(Boolean).join(" + ")
      for (const more of hasMore ? [false, true] : [false]) {
        for (const dark of [false, true]) {
          const name = `${label ? label + " " : ""}${dark ? "dark" : "light"}${more ? " + more contrast" : ""}`
          out.push({ name, decls: composeScope(blocks, { theme, accent, dark, more }), more })
        }
      }
    }
  }
  return out
}

/* ---------- colour ---------- */

const toLab = converter("oklab")
const toRgb = converter("rgb")

export function resolveColor(value: string, decls: Decls, depth = 0): Color {
  if (depth > 20) throw new Error(`var() cycle in ${value}`)
  const v = value.trim()
  const ref = v.match(/^var\((--[\w-]+)\)$/)
  if (ref) {
    if (!decls[ref[1]]) throw new Error(`undefined ${ref[1]}`)
    return resolveColor(decls[ref[1]], decls, depth + 1)
  }
  const mix = v.match(/^color-mix\(\s*in\s+oklab\s*,\s*(.+?)\s+(\d+(?:\.\d+)?)%\s*,\s*(.+)\)$/)
  if (mix) {
    const a = toLab(resolveColor(mix[1], decls, depth + 1))
    const b = toLab(resolveColor(mix[3], decls, depth + 1))
    const p = Number(mix[2]) / 100
    // CSS mixes premultiplied: mixing with `transparent` keeps the colour and lowers alpha.
    const [wa, wb] = [(a.alpha ?? 1) * p, (b.alpha ?? 1) * (1 - p)]
    const alpha = wa + wb
    const lerp = (x = 0, y = 0) => (alpha ? (x * wa + y * wb) / alpha : 0)
    return { mode: "oklab", l: lerp(a.l, b.l), a: lerp(a.a, b.a), b: lerp(a.b, b.b), alpha }
  }
  const c = parse(v)
  if (!c) throw new Error(`can't parse colour "${v}"`)
  return c
}

/** Composite a translucent colour over an opaque one. */
export function over(fg: Color, bg: Color): Color {
  const a = fg.alpha ?? 1
  if (a >= 1) return fg
  const f = toRgb(fg)
  const b = toRgb(bg)
  return { mode: "rgb", r: f.r * a + b.r * (1 - a), g: f.g * a + b.g * (1 - a), b: f.b * a + b.b * (1 - a) }
}

/* ---------- rules ---------- */

export const SURFACES = ["--background", "--sunken", "--popover"]

/** The floors: body text 7:1, secondary text and status colours 4.5:1, the accent and focus ring 3:1. */
export const RULES: Rule[] = [
  ["--foreground", [...SURFACES, "--muted", "--selected", "--destructive-subtle"], 7],
  ["--muted-foreground", [...SURFACES, "--muted", "--selected"], 4.5],
  ["--faint-foreground", SURFACES, 4.5],
  ["--primary-foreground", ["--primary"], 4.5],
  ["--background", ["--destructive"], 4.5],
  ["--inverse-foreground", ["--inverse"], 4.5],
  ["--destructive", ["--background", "--popover", "--destructive-subtle"], 4.5],
  ["--success", ["--background", "--popover", "--success-subtle"], 4.5],
  ["--warning", ["--background", "--popover", "--warning-subtle"], 4.5],
  ["--info", ["--background", "--popover", "--info-subtle"], 4.5],
  ["--primary", ["--background", "--popover"], 3],
  ["--ring", ["--background", "--popover"], 3],
]

/**
 * data-contrast="more" (and the OS's "increase contrast"): secondary text reaches AAA,
 * meta text 5.5:1, and control edges become visible boundaries (WCAG 1.4.11, 3:1).
 */
export const MORE_RULES: Rule[] = [
  ["--muted-foreground", [...SURFACES, "--muted"], 7],
  ["--faint-foreground", SURFACES, 5.5],
  ["--input", ["--background", "--popover"], 3],
]

/** Rules for a scope: the floors, every categorical colour it declares, and the stricter set under "more". */
export function rulesFor(decls: Decls, more = false): Rule[] {
  const cats = [...new Set(Object.keys(decls).flatMap((k) => k.match(/^--cat-([a-z]+)$/)?.[1] ?? []))]
  return [...RULES, ...cats.map((c): Rule => [`--cat-${c}`, [...SURFACES, `--cat-${c}-subtle`], 4.5]), ...(more ? MORE_RULES : [])]
}

/** Every pair a rule names, measured. A token that is missing or doesn't resolve is reported as a failed check. */
export function checkContrast(decls: Decls, rules: Rule[] = rulesFor(decls)): Check[] {
  const out: Check[] = []
  let canvas: Color
  try {
    canvas = resolveColor("var(--background)", decls)
  } catch (e) {
    return [{ fg: "--background", bg: "--background", ratio: 0, min: 1, ok: false, detail: (e as Error).message }]
  }
  for (const [fg, bgs, min] of rules) {
    for (const bg of bgs) {
      try {
        const b = over(resolveColor(`var(${bg})`, decls), canvas)
        const f = over(resolveColor(`var(${fg})`, decls), b)
        const ratio = wcagContrast(f, b)
        out.push({ fg, bg, ratio, min, ok: ratio >= min, detail: `${formatRgb(f)} on ${formatRgb(b)}` })
      } catch (e) {
        out.push({ fg, bg, ratio: 0, min, ok: false, detail: (e as Error).message })
      }
    }
  }
  return out
}

/**
 * Contrast matrix for every theme scope: light and dark, each neutral preset
 * (data-theme), each accent preset (data-accent) on top of each of those, and
 * each again under data-contrast="more". Reads the CSS, resolves var() and
 * color-mix(in oklab, …), flattens alpha over the surface, and checks WCAG
 * ratios (contrast-lib.ts). Turning a knob that breaks legibility fails here,
 * not in production.
 */
import fs from "node:fs"
import path from "node:path"
import { describe, expect, it } from "vitest"
import { checkContrast, parseBlocks, rulesFor, themeScopes } from "./contrast-lib"
import { loadConfig, root, themePaths } from "./guard-lib"

const cfg = loadConfig()

const blocks = themePaths(cfg)
  .filter((f) => fs.existsSync(path.join(root, f)))
  .flatMap((f) => parseBlocks(fs.readFileSync(path.join(root, f), "utf8")))

// A token a rule names that is missing or doesn't resolve fails its check:
// that means broken focus rings or invisible text, not a skipped rule.
const scopes = themeScopes(blocks)

describe("theme contrast", () => {
  it("finds the theme", () => {
    const light = scopes.find((s) => s.name === "light")
    expect(Object.keys(light?.decls ?? {}).length, `no :root tokens in ${cfg.themeFiles.join(", ")}`).toBeGreaterThan(10)
  })

  it('the OS "increase contrast" setting and data-contrast="more" set the same values', () => {
    const os = blocks.filter((b) => b.media?.includes("prefers-contrast: more")).map((b) => b.decls)
    const attr = blocks.filter((b) => !b.media && /\[data-contrast="more"\]/.test(b.selector)).map((b) => b.decls)
    expect(os).toEqual(attr)
  })

  // one test per neutral × accent, covering light, dark and "more contrast" for each
  const groups = new Map<string, typeof scopes>()
  for (const s of scopes) {
    const key = s.name.replace(/ ?(light|dark)( \+ more contrast)?$/, "") || "default"
    groups.set(key, [...(groups.get(key) ?? []), s])
  }

  for (const [group, list] of groups) {
    it(`${group}: text and accents meet WCAG`, () => {
      const fails = list.flatMap((s) =>
        checkContrast(s.decls, rulesFor(s.decls, s.more))
          .filter((c) => !c.ok)
          .map((c) => `${s.name}: ${c.fg} on ${c.bg}: ${c.ratio.toFixed(2)} < ${c.min}  (${c.detail})`),
      )
      expect(fails, fails.join("\n")).toEqual([])
    })
  }
})

/**
 * Design guards: values come from the theme, overlays from the kit.
 * Fix the code, or add `design-allow: <reason>` on the line.
 */
import { describe, expect, it } from "vitest"
import path from "node:path"
import { isCommentLine, loadConfig, report, scan, sourceFiles } from "./guard-lib"

const cfg = loadConfig()
const files = sourceFiles(cfg)

const palette =
  "slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose"
const utilities = "bg|text|border|border-[trblxy]|ring|ring-offset|outline|fill|stroke|from|via|to|divide|decoration|placeholder|caret|accent|shadow"

describe("design guards", () => {
  it("scans some files", () => {
    expect(files.length).toBeGreaterThan(0)
  })

  it("uses no raw colours outside the theme", () => {
    // Comments are skipped: "(#123)" there is an issue or PR number, not a colour.
    const hex = scan(files, /(^|[\s"'`(:,=[])#(?:[0-9a-fA-F]{3,4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})(?![\w-])/, (_, line) => !isCommentLine(line))
    const fn = scan(files, /\b(?:rgba?|hsla?|oklch|oklab|lab|lch|hwb)\(\s*[\d.]/)
    const named = scan(files, new RegExp(`(?<![\\w-])(?:${utilities})-(?:white|black|(?:${palette})-\\d{2,3})(?![\\w-])`))
    const arbitrary = scan(files, new RegExp(`(?<![\\w-])(?:${utilities})-\\[(?:#|rgb|hsl|oklch)`))
    const hits = [...hex, ...fn, ...named, ...arbitrary]
    expect(hits, `Raw colours — use semantic tokens (bg-background, text-muted-foreground, …):\n${report(hits)}`).toEqual([])
  })

  it("keeps text at 12px or larger, from the type scale", () => {
    const small = (px: string) => Number(px) < 12
    const tw = scan(files, /\btext-\[(\d+(?:\.\d+)?)px\]/, (m) => small(m[1]))
    const tw2 = scan(files, /\btext-\[\d/, () => true) // any arbitrary size, small or not
    const css = scan(files, /font-size:\s*(\d+(?:\.\d+)?)px/, (m) => small(m[1]))
    const rn = scan(files, /fontSize:\s*(\d+(?:\.\d+)?)/, (m) => small(m[1]))
    const tiny = scan(files, /\btext-(?:2xs|\[0?\.\d+rem\])/)
    const hits = [...new Map([...tw, ...tw2, ...css, ...rn, ...tiny].map((h) => [`${h.file}:${h.line}`, h])).values()]
    expect(hits, `Type outside the scale — use text-caption … text-hero:\n${report(hits)}`).toEqual([])
  })

  it("uses the kit for dialogs and overlays", () => {
    // Bare calls only: a method of the same name (notify.prompt) is fine; window.* is caught below.
    const native = scan(files, /(?<![.\w$])(?:alert|confirm|prompt)\(\s*["'`]/)
    const winNative = scan(files, /\bwindow\.(?:alert|confirm|prompt)\(/)
    const uiDirs = cfg.uiDirs.map((d) => path.normalize(d) + path.sep)
    const outsideKit = files.filter((f) => !uiDirs.some((d) => path.normalize(f).startsWith(d)))
    const handRolled = scan(outsideKit, /\bfixed\s+inset-0\b/)
    const hits = [...native, ...winNative, ...handRolled]
    expect(hits, `Use Dialog / Drawer / ConfirmDialog / notify from the kit:\n${report(hits)}`).toEqual([])
  })

  it("uses no emoji as icons", () => {
    const hits = scan(files, /\p{Emoji_Presentation}/u, (_m, line) => !line.trim().startsWith("//") && !line.trim().startsWith("*"))
    expect(hits, `Icons come from lucide-react, not emoji:\n${report(hits)}`).toEqual([])
  })
})

/**
 * Shared helpers for the design guards. Config comes from
 * design-guard.config.json at the project root (all keys optional):
 *   sourceDirs   folders to scan                      ["src"]
 *   themeFiles   files allowed to hold raw values     ["src/styles/jim-theme.css"]
 *   presetFiles  preset css files or folders          ["src/styles/presets"]
 *   uiDirs       kit folders allowed to build overlays ["src/components/ui"]
 *   ignore       path substrings to skip              []
 * Any line can opt out with a reason: `design-allow: <why>` on that line or
 * the line above. No reason, no exception.
 */
import fs from "node:fs"
import path from "node:path"

export type GuardConfig = {
  sourceDirs: string[]
  themeFiles: string[]
  presetFiles: string[]
  uiDirs: string[]
  ignore: string[]
}

export const root = process.cwd()

export function loadConfig(): GuardConfig {
  const file = path.join(root, "design-guard.config.json")
  const user = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, "utf8")) : {}
  return {
    sourceDirs: ["src"],
    themeFiles: ["src/styles/jim-theme.css"],
    presetFiles: ["src/styles/presets"],
    uiDirs: ["src/components/ui"],
    ignore: [],
    ...user,
  }
}

const exts = /\.(tsx?|jsx?|vue|svelte|css|scss)$/

export function walk(dir: string, out: string[] = []): string[] {
  const abs = path.join(root, dir)
  if (!fs.existsSync(abs)) return out
  if (fs.statSync(abs).isFile()) return exts.test(abs) ? [...out, dir] : out
  for (const e of fs.readdirSync(abs, { withFileTypes: true })) {
    if (e.name === "node_modules" || e.name.startsWith(".")) continue
    const rel = path.join(dir, e.name)
    if (e.isDirectory()) walk(rel, out)
    else if (exts.test(e.name)) out.push(rel)
  }
  return out
}

export function themePaths(cfg: GuardConfig) {
  return [...cfg.themeFiles, ...cfg.presetFiles.flatMap((p) => walk(p))].map((p) => path.normalize(p))
}

export function sourceFiles(cfg: GuardConfig) {
  const theme = new Set(themePaths(cfg))
  return cfg.sourceDirs
    .flatMap((d) => walk(d))
    .filter((f) => !theme.has(path.normalize(f)))
    .filter((f) => !/\.test\.[tj]sx?$/.test(f) && !f.includes(`${path.sep}guards${path.sep}`))
    .filter((f) => !cfg.ignore.some((i) => f.includes(i)))
}

export type Hit = { file: string; line: number; text: string }

/** Lines matching `re`, minus those carrying a `design-allow: reason`. */
export function scan(files: string[], re: RegExp, keep: (m: RegExpMatchArray, line: string) => boolean = () => true): Hit[] {
  const hits: Hit[] = []
  for (const file of files) {
    const lines = fs.readFileSync(path.join(root, file), "utf8").split("\n")
    lines.forEach((line, i) => {
      const allowed = /design-allow:\s*\S/.test(line) || /design-allow:\s*\S/.test(lines[i - 1] ?? "")
      if (allowed) return
      for (const m of line.matchAll(new RegExp(re.source, re.flags.includes("g") ? re.flags : re.flags + "g"))) {
        if (keep(m, line)) {
          hits.push({ file, line: i + 1, text: line.trim().slice(0, 140) })
          break
        }
      }
    })
  }
  return hits
}

/** A line that is only a comment (`//`, `/*`, ` * `, `<!--`): it can't style anything. */
export function isCommentLine(line: string) {
  return /^\s*(?:\/\/|\/\*|\*|<!--)/.test(line)
}

export function report(hits: Hit[]) {
  return hits.map((h) => `  ${h.file}:${h.line}  ${h.text}`).join("\n")
}
